BEGIN TRANSACTION;
CREATE TABLE allocations (id TEXT PRIMARY KEY, seq INTEGER NOT NULL, payment_id TEXT NOT NULL,
              invoice_id TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE batches (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE coverage (id TEXT PRIMARY KEY, seq INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE customers (id TEXT PRIMARY KEY, seq INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE events (
              seq INTEGER PRIMARY KEY AUTOINCREMENT, request_id TEXT NOT NULL,
              kind TEXT NOT NULL, at TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE fixtures (id INTEGER PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE idempotency (
              key TEXT PRIMARY KEY, payload_hash TEXT NOT NULL, request_id TEXT NOT NULL);
CREATE TABLE invoices (id TEXT PRIMARY KEY, seq INTEGER NOT NULL, customer_id TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE meta (key TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE notes (id TEXT PRIMARY KEY, seq INTEGER NOT NULL, data TEXT NOT NULL);
CREATE TABLE opening_balances (id TEXT PRIMARY KEY, seq INTEGER NOT NULL, customer_id TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE payments (id TEXT PRIMARY KEY, seq INTEGER NOT NULL, customer_id TEXT NOT NULL, data TEXT NOT NULL);
CREATE TABLE profiles (signature TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE record_ops (key TEXT PRIMARY KEY, payload_hash TEXT NOT NULL, result TEXT NOT NULL);
CREATE TABLE requests (id TEXT PRIMARY KEY, data TEXT NOT NULL);
CREATE TABLE runs (
              id TEXT PRIMARY KEY, request_id TEXT NOT NULL, request_version INTEGER NOT NULL,
              status TEXT NOT NULL, data TEXT NOT NULL);
CREATE UNIQUE INDEX one_running_run ON runs(request_id) WHERE status = 'running';
CREATE INDEX invoices_by_customer ON invoices(customer_id);
CREATE INDEX payments_by_customer ON payments(customer_id);
CREATE INDEX allocations_by_payment ON allocations(payment_id);
CREATE INDEX allocations_by_invoice ON allocations(invoice_id);
DELETE FROM "sqlite_sequence";
COMMIT;
